import{_ as t}from"./chunks/home.pc.ko.DgmCh8Ar.js";import{_ as e}from"./chunks/home-estop.pc.ko.DDxZsvoM.js";import{_ as d,o as r,c,a5 as n}from"./chunks/framework.BYXPg_yw.js";const k=JSON.parse('{"title":"제어 홈","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/control-home.md","filePath":"ko/manual/gui/control-home.md","lastUpdated":1793350928000}'),s={name:"ko/manual/gui/control-home.md"};function a(g,o,l,i,p,h){return r(),c("div",null,[...o[0]||(o[0]=[n('<h1 id="제어-홈" tabindex="-1">제어 홈 <a class="header-anchor" href="#제어-홈" aria-label="Permalink to &quot;제어 홈&quot;">​</a></h1><p>제어 홈은 로봇을 조종하는 화면입니다. 허브에서 <strong>컨트롤</strong>을 눌러 엽니다. 화면 전체가 뷰포트여서 카메라 영상이나 3D 뷰가 여기에 나오고, 왼쪽에는 모션 카드, 오른쪽에는 <strong>관측</strong> 카드가 붙습니다. 게임패드가 없으면 아래 양쪽 구석에 가상 조이스틱이 하나씩 생깁니다.</p><p><img src="'+t+'" alt="제어 홈"></p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>이 화면의 모션 버튼은 모두 실제 로봇을 움직입니다. <strong>로봇이 움직이는 동안에는 사람·동물·장애물을 로봇에서 2 m 이상 떨어뜨려 두십시오.</strong> 버튼을 누르기 전에 주변을 살피고, <code>E-STOP</code>에 손이 닿는 자리에 있으십시오.</p></div><h2 id="상단바" tabindex="-1">상단바 <a class="header-anchor" href="#상단바" aria-label="Permalink to &quot;상단바&quot;">​</a></h2><p>상단바는 영상 위에 두 묶음으로 나뉘어 떠 있습니다. 왼쪽부터 순서대로 봅니다.</p><table tabindex="0"><thead><tr><th>요소</th><th>표시 / 동작</th></tr></thead><tbody><tr><td>로고</td><td>화면 메뉴를 엽니다 — <strong>허브</strong>, <code>컨트롤</code>, <code>대시보드</code>, <code>설정</code>, <code>정비</code>, <code>로그</code>, <code>미디어</code>, <code>가이드</code>, <code>업데이트</code>. 제어 화면을 떠나면 로봇은 그 자리에 서고, 연결은 끊기지 않습니다</td></tr><tr><td>상태 불빛</td><td>초록·주황·빨강 중 하나가 천천히 깜빡입니다. 위험하면 빠르게 깜빡이고, 연결되지 않았으면 깜빡이지 않는 빨강입니다. 탭하면 <strong>시스템 종합 상태</strong>가 열립니다(<a href="/RBQ/nightly/ko/manual/gui/connection.html#connection-status-in-the-top-bar">연결</a> 참고)</td></tr><tr><td>보행 칩</td><td>로봇의 현재 보행 상태 이름을 상태별 색으로 보여 줍니다(예: <code>STANDING</code>). 연결되지 않았으면 보이지 않습니다</td></tr><tr><td><code>SLAM</code> 칩</td><td>외부 조종(SLAM·SDK)이 켜져 있을 때만 나타납니다. 탭하면 조종권이 앱으로 돌아옵니다</td></tr><tr><td>신호 막대</td><td>WiFi 신호 세기와, 로봇 링크로 지금 오가는 속도</td></tr><tr><td>로그 배지</td><td>아직 확인하지 않은 로그 알림</td></tr><tr><td><strong>로봇</strong> 배터리, 기기 배터리</td><td>로봇 배터리 잔량(충전 중이면 충전 표시)과 이 기기의 배터리. 로봇 배터리를 누르면 <strong>배터리 상세</strong>가 열립니다 — 전압, CAN-FD 로봇에서는 80%까지 걸리는 시간, 충전 경고</td></tr><tr><td><code>E-STOP</code></td><td>비상 정지 — 아래에서 설명합니다</td></tr><tr><td>종료</td><td>데스크탑 빌드에만 있습니다. <strong>앱을 종료할까요?</strong> 로 한 번 물어본 뒤 앱을 닫습니다. 로봇은 계속 동작합니다</td></tr></tbody></table><p>로봇이 끊긴 뒤 8초가 지나도 다시 붙지 않으면 앱이 스스로 허브로 넘어갑니다. 연결은 허브에서 하기 때문입니다. 연결된 로봇이 바뀌는 순간에도 허브로 돌아가니, 고르지 않은 로봇을 조종하게 될 일은 없습니다.</p><p>뒤로 가기(안드로이드 뒤로 버튼, PC·스팀덱의 <code>Esc</code>)는 이 화면에서 <strong>허브</strong>로 갑니다. 로고 메뉴의 <strong>허브</strong>와 같습니다. 게임패드 <code>B</code>는 이 화면에서 로봇 버튼이므로 화면을 옮기지 않습니다. PC·스팀덱에서는 <code>B</code>를 로봇 버튼으로 쓰지 않는 화면에서 뒤로 가기입니다. 허브에서 뒤로 가면 <strong>앱을 종료할까요?</strong> 로 한 번 물어봅니다(안드로이드·데스크탑).</p><h3 id="e-stop" tabindex="-1">E-STOP <a class="header-anchor" href="#e-stop" aria-label="Permalink to &quot;E-STOP&quot;">​</a></h3><p><code>E-STOP</code>은 한 번 탭으로는 발동하지 않습니다. 누르면 <strong>비상 정지하시겠습니까?</strong> 확인 창이 열리고, <em>로봇이 즉시 모든 동작을 멈추고 힘을 차단합니다. 제어를 다시 시작하려면 재초기화가 필요합니다.</em> 라고 알려 줍니다. <strong>정지</strong>를 누르면 실행하고, <strong>취소</strong>를 누르면 돌아갑니다. 메뉴가 열려 있을 때를 포함해 어느 화면에서나 똑같이 동작합니다.</p><p><img src="'+e+'" alt="E-STOP 확인"></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>비상 정지한 뒤에는 로봇에 모터 전원이 들어오지 않습니다. 다시 움직이려면 아래 <strong>자동 기동</strong>으로 되살려야 합니다. 시퀀스가 어디서 멈췄는지는 단계 칩이 알려 줍니다.</p></div><h3 id="소유권" tabindex="-1">소유권 <a class="header-anchor" href="#소유권" aria-label="Permalink to &quot;소유권&quot;">​</a></h3><p>로봇은 한 번에 한 기기만 조종합니다. 다른 기기가 제어권을 쥐고 있으면 상태 불빛이 주황으로 바뀌고, <strong>시스템 종합 상태</strong>의 <strong>소유권</strong> 행에 <code>가져오기 ▸</code> 가 뜹니다 — 탭하면 제어권을 되찾습니다. SLAM이나 SDK 프로그램이 조종하는 동안에는 대신 <code>SLAM</code> 칩이 보입니다.</p><p>다른 기기가 제어권을 쥐고 있는 동안 이 기기는 관전합니다. 화면은 그대로 보이고 상단 바 아래 조작은 잠기며, 위쪽 <code>관전</code>을 누르면 제어권을 가져올 수 있습니다. <a href="/RBQ/nightly/ko/manual/gui/emergency.html#spectating">관전</a> 참고.</p><h2 id="자동-기동" tabindex="-1">자동 기동 <a class="header-anchor" href="#자동-기동" aria-label="Permalink to &quot;자동 기동&quot;">​</a></h2><p>로봇의 모터 제어가 켜지기 전까지는 뷰포트 아래 중앙에 초록색 <strong>자동 기동</strong> 버튼이 떠 있습니다. 연결되지 않았으면 회색입니다. 탭하면 <strong>자동 기동</strong> 창이 열립니다. 창은 항상 화면 가운데에 고정됩니다 — 화면이 짧으면 창 안의 <strong>기동 시퀀스</strong> 목록만 스크롤되고 버튼은 늘 보입니다. 가로로 든 폰처럼 화면이 낮으면 단계마다 한 줄로 접혀 나오고, 줄을 탭하면 세부가 펼쳐지거나 접힙니다. 진행 중인 단계와 실패·경고가 난 단계는 저절로 펼쳐집니다.</p><ol><li>안내를 먼저 읽습니다 — <em>로봇을 평평한 바닥에 두고 모든 발과 무릎이 지면에 닿아 있는지 확인하세요.</em></li><li>단계 칩 다섯 개가 시퀀스를 보여 줍니다: <strong>POWER</strong>, <strong>CAN-BUS</strong>, <strong>HOMING</strong>, <strong>IMU-CHECK</strong>, <strong>START</strong>. 아직 끝나지 않은 <strong>CAN-BUS</strong>·<strong>HOMING</strong> 칩은 탭해서 그 단계만 따로 돌릴 수 있습니다.</li><li><strong>자동 기동</strong>을 누릅니다. 창은 그대로 열려 있고, 칩 아래 <strong>기동 시퀀스</strong> 패널이 사전 확인 → Leg 전원 → 데이터 속도 → 관절 통신 → 모터 파라미터 → 홈 위치 → IMU → 제어 활성 순으로 <strong>통과 / 실패 / 경고 / 진행 중</strong>을 하나씩 채웁니다.</li><li>어느 단계가 실패하면 패널이 원인과 조치를 함께 알려 줍니다. 예를 들어 <em>이미 서 있는 상태입니다 — 로봇을 앉힌 뒤 다시 시작하세요.</em> 처럼 나옵니다. 조치한 뒤 <strong>다시 시작</strong>을 누릅니다.</li><li>시퀀스가 <strong>완료</strong>로 바뀌면 <strong>닫기</strong>를 누릅니다. 이 창에서 지켜본 기동이 마지막 단계까지 통과하면 <strong>다시 시작</strong>이 사라지고 <strong>닫기</strong>만 남습니다. 실수로 두 번 돌릴 일이 없습니다.</li></ol><p>같은 시퀀스를 상태 불빛에서도 시작할 수 있습니다: <strong>시스템 종합 상태 › ▶ 자동 기동 (전체 시퀀스)</strong>.</p><h2 id="뷰포트와-소스-선택" tabindex="-1">뷰포트와 소스 선택 <a class="header-anchor" href="#뷰포트와-소스-선택" aria-label="Permalink to &quot;뷰포트와 소스 선택&quot;">​</a></h2><p>뷰포트 위쪽 중앙의 드롭다운으로 무엇을 볼지 고릅니다. 로봇의 실시간 모델인 <code>3D</code>는 언제나 있고, 카메라 소스는 로봇이 그 카메라를 알아봤을 때만 목록에 올라옵니다: <strong>전방</strong>, <strong>후방</strong>, <strong>좌측</strong>, <strong>우측</strong>, <strong>계단</strong>, <strong>4분할</strong>, <strong>파노라마</strong>, <code>CCTV</code>, <strong>열화상</strong>, <strong>PTZ 합성</strong>, 그리고 LiDAR 장착 로봇의 <code>SLAM</code>. 목록 바깥을 탭하면 소스를 바꾸지 않고 닫힙니다.</p><p>CAN-FD 기체에서 <a href="/RBQ/nightly/ko/manual/gui/maintenance.html#led-bottom">하단 상태 LED</a>가 켜져 있으면 <code>3D</code>와 <strong>계단</strong>의 3D에도 같은 색의 빛이 나옵니다. 몸체 아래 LED 자리와 다리, 발 높이의 바닥을 비추고, 깜빡이는 LED는 같은 박자로 깜빡입니다. 바닥에는 LED마다 원이 하나씩 생겨 조금 어긋나 겹치고, 겹친 곳은 두 색이 섞입니다. 몸을 낮추면 바닥 빛이 작아집니다. LiDAR·heightmap 점이나 장애물 지도를 그리는 동안에는 겹치지 않게 나오지 않습니다.</p><p>PTZ 계열 소스를 고르면 팬·틸트·줌 패널이 영상 위에 뜹니다. 손잡이를 잡아 옮길 수 있습니다.</p><p>도킹이 도는 동안에는 선택기가 <code>도킹</code>으로 바뀌고 열리지 않습니다 — 닫을 때까지 뷰포트는 <a href="/RBQ/nightly/ko/manual/gui/camera-vision.html#dock-view">Dock View</a>가 씁니다.</p><h2 id="왼쪽-카드-—-모션" tabindex="-1">왼쪽 카드 — 모션 <a class="header-anchor" href="#왼쪽-카드-—-모션" aria-label="Permalink to &quot;왼쪽 카드 — 모션&quot;">​</a></h2><p>로봇을 움직이는 것은 모두 왼쪽에 모여 있습니다.</p><ul><li><strong>카드</strong>: 접혀 있으면 걷는 사람 아이콘이 든 둥근 유리 버튼입니다. 누르면 동그라미가 카드로 늘어나고, 카드 윗줄을 누르면 다시 접힙니다. 카드마다 펼침 상태를 기억하며, 처음에는 둘 다 펼쳐져 있습니다.</li><li><strong>본문</strong>: 고정 모션 버튼 <code>SIT</code>, <code>STAND</code>, <code>WALK</code>, <code>STAIRS</code>, <code>DOCKING</code>(도킹이 가능할 때만), 그리고 전체 모션 그리드를 여는 점선 버튼 <strong>모션</strong>이 있습니다. 로봇의 현재 보행 상태와 맞는 버튼이 강조됩니다. <a href="/RBQ/nightly/ko/manual/gui/motion-commands.html">모션 명령</a>을 참고하세요.</li><li><strong>도구 버튼</strong>: 카드 밖, 왼쪽 조이스틱 바로 오른쪽에 작은 버튼이 한 줄로 놓입니다. 게임패드 모드에서는 왼쪽 가장자리로 갑니다. 하나를 누르면 그 줄 위로 해당 패널이 열립니다. <ul><li><strong>주행</strong> — 속도·본체 높이·기울기 슬라이더 (<a href="/RBQ/nightly/ko/manual/gui/motion-commands.html#drive-parameters">주행 파라미터</a>).</li><li><strong>팔</strong> — 매니퓰레이터가 달린 로봇에만 나옵니다.</li><li><strong>조종</strong> — 입력 모드 <strong>자동 / 가상 / 패드</strong>와 실시간 게임패드 입력 맵. <em>자동</em>은 물리 게임패드가 연결되면 그쪽으로 넘깁니다. 초록 점이 있으면 외부 조종이 주행을 맡고 있다는 뜻입니다.</li></ul></li><li>카드가 화면보다 길면 아래에 <code>▾</code>가 붙어 스크롤된다는 것을 알려 줍니다.</li></ul><p>팔 조작 메뉴는 팔 48V 전원이 켜져 있고 팔 관절 6개의 통신이 확인될 때만 표시됩니다. 팔 전원을 끄면 조작 메뉴가 숨겨집니다. 전원이 끊기면 수동 입력을 해제합니다. 수동제어 화면에서 나갈 때 팔 접기를 요청하지 않으며, 전원을 다시 켠 뒤에는 수동제어를 직접 다시 시작해야 합니다. 시뮬레이션에는 전원 분배 장치가 없으므로 전원 조건을 적용하지 않습니다.</p><p><code>팔</code> 메뉴에는 <code>수동제어</code>·<code>팔 모션</code> 두 화면 진입과 <code>Folding</code>·<code>Ready</code>·<code>Straight</code>·<code>Lift</code> 네 가지 기본 자세가 있습니다. 자세 버튼은 화면을 열지 않고 그 자리에서 팔을 움직이며, 팔 제어가 시작돼 있고 팔 위치 고정이 풀려 있을 때만 눌립니다.</p><p><code>팔</code> → <code>팔 모션</code>을 누르면 모션 목록과 실시간 로봇·팔 3D 화면이 열립니다. 목록에는 <code>Greeting</code>·<code>Multi joint</code>·<code>Auto Recovery</code>·<code>Damping Mode</code>가 있습니다.</p><p>로봇은 첫 모션이 준비 자세가 아니면 명령을 받아들이지 않습니다. 화면에 들어온 뒤 <code>준비 자세 (Ready)</code>를 한 번 누르기 전에는 나머지 모션이 비활성으로 보이며, 안내 문구가 표시됩니다. 화면을 나갔다 들어오면 다시 눌러야 합니다. 데모 모션은 팔을 크게 움직이므로 주변을 비우고 실행합니다.</p><p><code>팔</code> → <code>수동제어</code>를 누르면 몸통 전방 카메라와 하나로 합친 로봇·팔 3D 조작 화면이 열립니다. 그리퍼는 주황색으로 강조합니다. <code>EE 중심</code>은 측정된 팔 끝을 가까이 따라가며, 오른쪽 위 PIP에 전체 로봇 3D를 함께 표시합니다. PIP 또는 <code>전체 보기</code>를 누르면 전체 로봇이 커지고, <code>EE 중심</code>으로 돌아올 수 있습니다. 두 시점은 같은 실시간 로봇 모형을 사용합니다. EE 좌표축은 선택한 제어 기준을 따르고 화면 크기와 줌에 맞춰 표시합니다. 화살표와 터치 영역을 넓혔으며 기본 길이는 이전의 140%입니다. 3D 상단의 <code>조작 표시</code> 설정에 있는 <code>축 크기</code> 슬라이더 또는 <code>축 작게</code>·<code>축 크게</code>로 100~200%를 조절하고 <code>기본값</code>으로 140%를 복원합니다. 설정은 이 기기에 저장되며 화면 가장자리에서는 축이 잘리지 않도록 크기가 제한됩니다. 설정을 열면 현재 입력을 정지하며 표시 크기 변경은 이동 속도나 제어 기준을 바꾸지 않습니다. 같은 설정에서 A(축 발광), B(잡은 지점과 손가락의 연결선), C(방향 리본), B+C(연결선과 리본)를 선택해 비교할 수 있습니다. 선택은 기기에 저장됩니다. 축을 잡으면 잡는 중 상태를 표시하고, 화면의 작은 데드존을 넘어 끌면 +/− 입력 방향을 표시합니다. 회전은 곡선 방향을 표시하며, 시점상 방향을 판별하기 어려운 축은 기존 위/아래 조작 방향으로 표시합니다. 손을 떼거나 조작이 취소되면 표시도 지웁니다. 이 그래픽은 사용자 입력을 표현하며 실제 이동·정지 완료, 이동 거리·속도·힘을 확인한 표시가 아닙니다. 핸드 카메라는 전방 영상 오른쪽 아래의 별도 PIP에 계속 표시하며, 카메라 두 영상은 하나의 합성 스트림을 사용합니다.</p><p>좁은 화면은 카메라 아래에 통합 3D를 배치합니다. 하단 조작 바는 고정되며 −/+ 및 그리퍼 터치 버튼을 키웠습니다. <code>버튼 조작</code>·<code>축 드래그</code> 전환으로 영상 크기나 3D 마운트가 바뀌지 않습니다. 웹·데스크탑에서는 조그 버튼을 누른 채 손가락이 버튼 밖으로 미끄러져도 입력을 유지합니다. 손을 떼거나 터치 취소·포인터 캡처 해제·두 번째 터치·포커스 이탈·버튼 비활성화 시 홀드를 취소합니다. 포커스된 버튼은 Space/Enter를 누르는 동안 조작하고 키를 떼면 멈춥니다. 상시 설명은 생략하되 연결·전원·오류·자세/좌표계 미수신 상태는 표시합니다. <code>3D 크게 보기</code>는 카메라와 통합 3D의 크기를 교환하고 <code>카메라 크게 보기</code>로 복구합니다. 넓은 화면은 구분선 드래그 또는 좌우 방향키로 열 너비를 조절합니다. 시점 변경과 크기 조절은 진행 중 입력을 취소합니다.</p><p>화면 진입만으로 팔을 움직이지 않습니다. <code>수동제어 시작</code>을 눌러 요청하면 준비 자세로 팔이 움직일 수 있습니다. 로봇이 수동제어 상태를 보고하면 EE·그리퍼 조작이 활성화됩니다. 통합 3D의 강조된 그리퍼에서 화살표를 잡고 축 방향으로 끌어 조작합니다. <code>회전</code>에서는 선택한 축의 곡선 화살표를 잡고 원을 따라 끕니다. 모델은 측정 관절각과 몸통 자세로 계산한 그리퍼 방향을 실시간으로 표시하며, RBA-1 손가락은 측정 개폐 상태도 반영합니다. EE 중심 시점은 측정 팔 끝의 위치를 따라가며, 자세가 없으면 수신 대기를 표시합니다. 클릭하거나 잡기만 해서는 움직이지 않으며, 화면에서 일정 거리 이상 끌어 시작점에서 벗어나 있는 동안 기존 속도로 조그합니다. 시작점으로 돌아오거나 손을 떼거나 터치가 취소되면 입력 정지를 요청합니다. 끈 거리로 실제 이동량이나 목표 자세를 지정하는 방식은 아닙니다. 드래그 방향의 기준은 잡은 순간에 고정되므로 실시간 모델 자세가 바뀌어도 조작 방향이 바뀌지 않습니다. 반대 방향으로 바꾸면 먼저 정지 요청이 접수된 뒤 새 방향을 시작합니다. 현재 시점에서 드래그 방향을 판별하기 어려운 축은 위로 끌면 +, 아래로 끌면 − 방향입니다. X/Roll은 빨강, Y/Pitch는 초록, Z/Yaw는 파랑이며, 회전 화살표는 <code>+</code> 방향을 표시합니다. EE 축을 잡으면 팔 조작이며, 그 밖의 3D 영역을 끌면 시점이 회전합니다. 전체 로봇 PIP는 시점만 전환하며 이동 명령을 보내지 않습니다. FC 기준에서 EE에 표시되는 이동 화살표는 발 배치에 따른 회전 보정까지 포함한 제어기의 수평 발 중심 좌표계입니다. EE 기준 이동 화살표와 회전 축은 팔 끝의 로컬 기준입니다. FC 표시는 로봇의 ManiControl과 Network도 새 빌드로 갱신해야 합니다. FC 정보가 없으면 body 기준 축을 대신 표시하지 않고 드래그 모델에 수신 대기를 표시하며, 기존 버튼 조작은 사용할 수 있습니다. 기존 축 선택·<code>−</code>/<code>+</code> 버튼은 <code>버튼 조작</code> 탭에서 사용합니다. <code>EE 조작 정지</code>는 접지 않고 표시합니다. 축·모드 변경, 조작 탭 전환, 두 번째 터치, 화면 이탈·앱 숨김은 현재 입력과 대기 중인 드래그 시작을 취소합니다. 그리퍼 열기·닫기는 별도의 홀드 조작으로 유지됩니다. <code>Fix</code>는 팔 위치를 고정하고 <code>Control</code>은 다시 수동제어를 허용합니다. <code>초기 위치 (Reset)</code>는 수동제어 진입을 다시 요청하며 현재 자세에 따라 준비 자세로 이동할 수 있습니다. <code>팔 접고 나가기</code>는 누르고 있던 입력을 정지하고 XYZ·RPY·그리퍼 정지 요청이 모두 접수된 뒤 Folding/Home 명령을 요청하고 제어 홈으로 돌아갑니다. 헤더의 화면 이동과 앱 내 뒤로 가기도 같은 접기 요청을 거칩니다. 연결된 상태에서 명령 전송 실패 시 화면에 남으며, 접기 완료를 기다리는 기능은 아닙니다. 연결이 끊기면 대기 중인 조작과 통신 큐의 수동제어 명령을 취소하고 자동 접기 없이 허브로 돌아갑니다. 허브에는 정지·접힘을 확인하지 못했다는 안내가 표시됩니다. 재연결로 조작이 자동 재개되지 않으며, 사용자가 상태를 확인하고 수동제어를 다시 시작해야 합니다. 로봇 측 정지·접기 완료를 보장하는 기능은 아닙니다. 브라우저 탭 종료·새로고침은 이 이동 절차를 보장하지 않습니다.</p><p>이동은 <code>FC 기준</code>(기존 발 중심 기준 이동) / <code>EE 기준</code> 중 선택합니다. EE 기준에서 +X는 그리퍼가 향하는 방향으로 전진하고 −X는 후퇴합니다. X/Y/Z 화살표는 팔 끝 자세를 따라 표시되며 축 드래그와 −/+ 버튼 모두 같은 기준으로 동작합니다. 새로 누를 때 측정 EE 축을 잡고 현재 자세 참조를 유지한 채 기존 조그 속도인 0.10 m/s로 이동을 요청합니다. 기준 전환은 현재 입력을 정지하며 새 움직임을 시작하지 않습니다. 회전은 항상 EE 기준입니다. 기존 작업 공간·지면 경계에서는 EE 접근 전체를 정지하며 실제 이동은 제어기와 관절 한계의 영향을 받습니다. 먼저 그리퍼를 직접 정렬해서 사용합니다. 물체 인식·자동 정렬·접촉 감지·자동 파지는 제공하지 않습니다. 이 기능은 GUI뿐 아니라 로봇의 ManiControl도 새 빌드로 갱신해야 하며 GUI만 갱신해서는 사용할 수 없습니다.</p><p>상단 조작 줄에는 <code>초기 위치 (Reset)</code>·<code>Fix</code>·<code>Control</code>·<code>팔 접고 나가기</code>와 함께 <code>Robot Control Mode</code>·<code>Chicken Head Mode</code>가 있습니다. 수동제어를 시작한 뒤 사용합니다. 두 모드는 팔 제어가 시작돼 있고 위치 고정이 풀려 있어야 사용할 수 있으며, 누르고 있던 EE 입력을 정지한 뒤 명령을 보냅니다. 모드 버튼을 누른 것만으로 로봇의 전환 완료를 판단하지 말고 상태와 로그를 확인합니다.</p><p>EE 위치에 따른 기존 pitch 추적을 사용합니다. 추가 base 높이 자동 조절은 사용하지 않습니다.</p><p>수동제어에서 <code>조작 표시</code> 옆 <code>EE 속도</code>를 열면 이동·회전 속도를 각각 10~100%로 설정하거나 <code>정밀</code>·<code>보통</code>·<code>빠르게</code>를 선택할 수 있습니다. 축 드래그와 −/+ 버튼에 함께 적용되고 이 기기에 저장됩니다. 설정을 열거나 속도를 바꾸면 현재 입력이 정지하며 창을 닫아도 자동 재개하지 않습니다. 퍼센트는 요청 속도이며 실측 속도나 이동 거리를 뜻하지 않습니다. 속도 지원이 없다고 표시되면 로봇 소프트웨어와 앱을 함께 업데이트하세요. 3D 화면은 현재 FC 방향을 따르며 실측 팔·EE 자세를 유지합니다.</p><h2 id="오른쪽-카드-—-관측" tabindex="-1">오른쪽 카드 — 관측 <a class="header-anchor" href="#오른쪽-카드-—-관측" aria-label="Permalink to &quot;오른쪽 카드 — 관측&quot;">​</a></h2><p><em>무엇을 보고 듣는가</em>에 해당하는 것은 모두 오른쪽에 있습니다.</p><ul><li><strong>카드</strong>: 접혀 있으면 둥근 유리 버튼이고, 펼치고 접는 방식은 왼쪽 카드와 같습니다.</li><li><strong>본문</strong>: <ul><li><strong>비전</strong> — 비전 토글이 모여 있습니다. <strong>P2G</strong>(Point-to-Go)도 여기 있는데, 소스가 <strong>전방</strong>일 때만 쓸 수 있습니다. P2G를 켜 두면 영상 속 바닥의 한 지점을 탭할 때 로봇이 그곳으로 걸어갑니다.</li><li><strong>3D 씬</strong> — 3D 뷰 설정. 소스가 <code>3D</code>일 때만 나옵니다.</li><li><strong>오디오</strong> — 로봇 소리 듣기, 볼륨, 장치. 초록 점이 있으면 듣기가 켜져 있습니다.</li><li><code>SLAM</code> — LiDAR 장착 로봇에만 나옵니다. <strong>SLAM / 내비</strong> 팝오버를 열고 화면을 <code>SLAM</code> 지도로 바꿉니다.</li><li><strong>PTZ</strong> — PTZ 카메라가 달린 로봇에만 나옵니다. 화면을 PTZ 카메라로 바꾸고, 다시 누르면 직전 소스로 돌아갑니다.</li></ul></li><li><strong>워키토키</strong>: 오른쪽 아래 버튼입니다. 오른쪽 조이스틱 바로 왼쪽에 있고, 게임패드 모드에서는 오른쪽 가장자리로 갑니다. 누르고 있는 동안 로봇 스피커로 말이 나가며, 그동안 <strong>송출 중</strong>으로 표시됩니다. 스피커 앰프가 꺼져 있으면 흐리게 보이고 눌리지 않습니다.</li><li><strong>사운드 · 촬영</strong>: <code>워키토키</code> 바로 왼쪽의 버튼 둘입니다. <code>사운드</code>는 소리를 골라 로봇에서 반복 재생합니다. <code>촬영</code>을 누르면 <code>사진</code>과 <code>녹화</code> 중 하나를 고르고, 녹화 중에는 버튼에 빨간 경과 시간이 뜨며 다시 누르면 멈춥니다. 화면이 좁아 가운데 계기와 닿으면 두 버튼이 <code>워키토키</code> 위로 세로로 쌓입니다. 자세한 내용은 <a href="/RBQ/nightly/ko/manual/gui/media.html#control-home">미디어</a>를 보세요.</li><li><strong>자이로</strong>와 <strong>속도 HUD</strong>는 영상 아래 중앙에 나란히 있습니다. 자이로를 탭하면 커집니다. 둘 다 <strong>앱 설정</strong>에서 끌 수 있습니다.</li><li><strong>시뮬레이터</strong>에서는 좌우 카드가 없고 화면을 3D 로 꽉 채웁니다. 로봇은 늘 걷기 상태이고, 아래 도구 줄에 <code>주행</code>·<code>레벨</code>·<code>리셋</code>이 놓입니다. 시점은 위 가운데 드롭다운에서 고릅니다. 진행 상황은 그 아래에 표시됩니다. 레벨과 시점은 <a href="./connection.html">연결</a>의 시뮬레이터 설명을 보세요.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>P2G</strong>가 켜진 동안에는 영상 전체가 명령 영역입니다 — 바닥을 탭할 때마다 로봇이 움직입니다. 다 쓰면 반드시 끄십시오.</p></div><h2 id="조이스틱과-입력-모드" tabindex="-1">조이스틱과 입력 모드 <a class="header-anchor" href="#조이스틱과-입력-모드" aria-label="Permalink to &quot;조이스틱과 입력 모드&quot;">​</a></h2><ul><li><strong>게임패드가 없으면</strong> — 터치 기기와 PC에서는 가상 조이스틱 두 개가 나옵니다. 축이 무엇을 하는지는 현재 모션에 따라 달라집니다. <a href="/RBQ/nightly/ko/manual/gui/motion-commands.html">모션 명령</a>의 축 표를 보세요.</li><li><strong>게임패드가 있으면</strong> — 물리 패드든 Steam Deck이든 가상 조이스틱이 사라지고 패드의 스틱으로 조종합니다. 영상을 넓게 보려면 카드를 접으십시오.</li><li>설정 › 게임패드의 <strong>원 스틱 모드</strong>는 좌우 스틱 역할을 바꿔 한 손으로도 조종할 수 있게 합니다.</li></ul><p><strong>키보드로 조종하기</strong> — 게임패드가 없는 PC에서는 가상 조이스틱과 함께 키보드로도 조종할 수 있습니다. 이 화면에서만 듣습니다. 허브나 설정에서는 같은 키를 눌러도 로봇이 꿈쩍하지 않습니다.</p><table tabindex="0"><thead><tr><th>키</th><th>하는 일</th></tr></thead><tbody><tr><td><kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd></td><td>왼쪽 스틱 — 앞뒤 · 좌우</td></tr><tr><td><kbd>Q</kbd> <kbd>E</kbd></td><td>오른쪽 스틱 좌 / 우 — 좌 / 우 회전</td></tr><tr><td><kbd>↑</kbd> <kbd>↓</kbd> <kbd>←</kbd> <kbd>→</kbd></td><td>오른쪽 스틱</td></tr></tbody></table><p>키를 누르고 있는 동안 로봇이 움직이고, 떼면 멈춥니다. 키보드에는 비상 정지 키가 없습니다 — <strong>E-STOP은 화면 오른쪽 위 버튼</strong>입니다.</p><p>연결된 동안에는 왼쪽 아래 구석에 현재 보행 상태 이름이 작은 HUD로 뜹니다.</p><h2 id="컴팩트-레이아웃" tabindex="-1">컴팩트 레이아웃 <a class="header-anchor" href="#컴팩트-레이아웃" aria-label="Permalink to &quot;컴팩트 레이아웃&quot;">​</a></h2><p>세로가 짧은 화면, 그러니까 폰이나 높이 500 px 미만의 창에서는 배치를 그대로 두고 요소만 작아집니다. 조이스틱·도구 버튼·워키토키는 구석으로 작게 들어가고, 왼쪽 카드는 그 위 공간까지만 차지하며 스크롤됩니다. 가로가 좁은 화면에서는 카드 폭도 좁아집니다. 빠지는 기능은 없습니다.</p><p>폭이 720 px 미만인 아주 작은 화면(작은 폰 가로 등)에서는 표시를 덜어 냅니다. 아래 도구 버튼과 <code>워키토키</code> 옆 버튼은 글자 없이 아이콘만 남고, 오른쪽 위 <code>E-STOP</code>은 비상 아이콘만 보이며, 전송량 칸의 신호 막대와 가운데 자이로가 작아지거나 빠집니다. 기능은 그대로입니다.</p><blockquote><p><strong>개발자 모드에서 더 나오는 것</strong>은 <a href="/RBQ/nightly/ko/manual/gui/developer-mode.html#control-home">개발자 모드</a>에 모아 두었습니다.</p></blockquote>',53)])])}const E=d(s,[["render",a]]);export{k as __pageData,E as default};
